/* ---------- gallery backdrop ---------- */
const skyU = { top: { value: new THREE.Color(0x07090d) }, mid: { value: new THREE.Color(0x2b2219) }, bot: { value: new THREE.Color(0x060709) } };
const sky = new THREE.Mesh(new THREE.SphereGeometry(90, 32, 16), new THREE.ShaderMaterial({
 uniforms: skyU, side: THREE.BackSide, depthWrite: false, fog: false,
 vertexShader: `varying vec3 vP; void main(){ vP = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.); }`,
 fragmentShader: `uniform vec3 top, mid, bot; varying vec3 vP;
  void main(){ float h = vP.y; vec3 c = h > 0. ? mix(mid, top, smoothstep(0.0, .5, h)) : mix(mid, bot, smoothstep(0.0, -.18, h));
  c *= mix(.45, 1.0, smoothstep(-0.3, 0.9, vP.x)); gl_FragColor = vec4(c, 1.); }`
}));
sky.renderOrder = -10; scene.add(sky);
const voidFloor = mesh(new THREE.CircleGeometry(48, 64), M.void, 0, -0.5, 0, false); voidFloor.rotation.x = -Math.PI / 2; scene.add(voidFloor);

const env = new THREE.Group(); scene.add(env);
/* plinth + ground */
const ZF = 1.4, XL = -4.4, XR = 4.4;
env.add(boxAt(XL - .06, XR + .06, -0.5, -0.05, -3.06, ZF + .06, M.plinth));
const edgeGlow = mesh(new THREE.BoxGeometry(XR - XL + .12, .006, .006), new THREE.MeshBasicMaterial({ color: 0xffe2b8, toneMapped: false, transparent: true, opacity: .55 }), 0, -0.052, ZF + .062, false);
env.add(edgeGlow);
env.add(boxAt(XL, -0.18, -0.05, 0, -3, ZF, M.wood, 2));
env.add(boxAt(0.18, 0.42, -0.05, -0.012, -3, ZF, M.gravel, .5));
env.add(boxAt(0.42, 2.7, -0.05, 0, -3, ZF, M.paver, 1.2));
env.add(boxAt(2.7, XR, -0.05, -0.006, -3, ZF, M.grass, 2));
/* ceiling slab with small eave */
const ceil = boxAt(XL, 0.46, 3.0, 3.24, -3, 0, M.slab, 1); ceil.castShadow = false; env.add(ceil);
env.add(boxAt(0.18, 0.46, 2.96, 3.0, -3, 0, M.render, .6));
/* back wall of the room */
env.add(boxAt(XL, -0.18, 0, 3.0, -3.0, -2.86, M.plaster, .8));
const skirt = std({ color: 0xf6f3ee, roughness: .5 });
env.add(boxAt(XL, -0.18, 0, .08, -2.86, -2.845, skirt), boxAt(-0.195, -0.18, 0, .08, -2.86, 0, skirt));

/* wall in section — layered, with notches that reveal penetrations */
const WALL = [[-0.18, -0.165, M.plaster, .6], [-0.165, 0.045, M.block, 1.2], [0.045, 0.155, M.wool, .5], [0.155, 0.18, M.render, .6]];
function buildWall(notches, nz) {
 const g = new THREE.Group();
 for (const [x0, x1, mat, s] of WALL) {
  g.add(boxAt(x0, x1, 0, 3.0, -3.0, nz, mat, s));
  let y = 0;
  for (const n of notches) { if (n[0] > y) g.add(boxAt(x0, x1, y, n[0], nz, 0, mat, s)); y = n[1]; }
  g.add(boxAt(x0, x1, y, 3.0, nz, 0, mat, s));
 }
 const ln = new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: .22 });
 const pts = [V(-0.18, 0, .002), V(-0.18, 3.24, .002), V(0.46, 3.24, .002), V(0.46, 2.96, .002), V(0.18, 2.96, .002), V(0.18, 0, .002)];
 g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), ln));
 return g;
}

/* ---------- interior set dressing ---------- */
const room = new THREE.Group(); env.add(room);
room.add(mesh(new RoundedBoxGeometry(2.5, .014, 2.8, 2, .006), std({ color: 0xb9ad9a, roughness: 1 }), -2.45, .007, -1.15));
const sofa = new THREE.Group(); sofa.position.set(-2.5, 0, -2.42); room.add(sofa);
const rb = (w, h, d, r, mat, x, y, z) => mesh(new RoundedBoxGeometry(w, h, d, 3, r), mat, x, y, z);
sofa.add(rb(2.0, .24, .84, .05, M.fabric, 0, .22, 0), rb(2.0, .5, .2, .08, M.fabric, 0, .55, -.32),
 rb(.2, .34, .86, .07, M.fabric, -.98, .4, 0), rb(.2, .34, .86, .07, M.fabric, .98, .4, 0),
 rb(.86, .14, .62, .06, M.fabric, -.44, .4, .08), rb(.86, .14, .62, .06, M.fabric, .44, .4, .08));
const pillow = rb(.42, .36, .12, .06, std({ color: 0xc9a46a, roughness: .95 }), -.62, .62, -.16); pillow.rotation.set(-.25, .2, .12); sofa.add(pillow);
for (const sx of [-.9, .9]) for (const sz of [-.34, .34]) sofa.add(mesh(new THREE.CylinderGeometry(.02, .015, .1, 10), M.oak, sx, .05, sz));
const table = new THREE.Group(); table.position.set(-2.45, 0, -1.2); room.add(table);
