/* ===================== per-frame visuals ===================== */
const SC = {}; for (const m of ['cool', 'heat']) { SC[m] = {}; for (const [k, v] of Object.entries(SEASON[m])) SC[m][k] = typeof v === 'number' && k.endsWith('I') ? v : new THREE.Color(v); }
const tmpC = new THREE.Color(), EV = new THREE.Color(0x2a6bff), CO = new THREE.Color(0xff5a2a), WHITE = new THREE.Color(0xffffff), FROST = new THREE.Color(0xdcefff), WARMC = new THREE.Color(0xffe6d2);
const LEDC = { cool: new THREE.Color(0x4f9dff), heat: new THREE.Color(0xff7a3a) };
const lc = (o, a, b, s) => o.lerpColors(a, b, s);
function updateVisuals(dt, t) {
 const k = 1 - Math.exp(-dt * (reduced ? 20 : 2.4)), heat = !isCool();
 state.season += ((heat ? 1 : 0) - state.season) * k; const s = state.season, A = SC.cool, B = SC.heat;
 lc(sun.color, A.sun, B.sun, s); sun.intensity = lerp(A.sunI, B.sunI, s);
 lc(hemi.color, A.hS, B.hS, s); lc(hemi.groundColor, A.hG, B.hG, s); hemi.intensity = lerp(A.hI, B.hI, s);
 lc(M.grass.color, A.grass, B.grass, s); lc(M.hedge.color, A.hedge, B.hedge, s); lc(treeMat.color, A.tree, B.tree, s);
 lc(M.paver.color, A.paver, B.paver, s); lc(M.gravel.color, A.paver, B.paver, s);
 lc(skyU.mid.value, A.skyMid, B.skyMid, s); lc(scene.fog.color, A.fog, B.fog, s);
 lc(roomLight.color, A.roomC, B.roomC, s); roomLight.intensity = lerp(A.roomI, B.roomI, s);
