   mat.emissive.lerp(cond ? CO : EV, k); mat.emissiveIntensity = lerp(mat.emissiveIntensity, cond ? .5 * pulse : .38, k);
   mat.color.lerp(cond ? WARMC : (side === 'out' && heat ? FROST : WHITE), k);
  }
  VIS[sys].led.emissive.lerp(heat ? LEDC.heat : LEDC.cool, k); VIS[sys].led.color.lerp(heat ? LEDC.heat : LEDC.cool, k);
  VIS[sys].rvLed.emissiveIntensity = lerp(VIS[sys].rvLed.emissiveIntensity, heat ? 4 : 0, k);
 }
 VIS.split.louver.rotation.z = lerp(VIS.split.louver.rotation.z, heat ? .95 : .22, k);
