 for (const key of ['in', 'out', 'sup', 'exh']) { const nv = TD[key] + (T[key] - TD[key]) * k; if (Math.abs(nv - TD[key]) > 1e-3) ch = true; TD[key] = Math.abs(nv - T[key]) < .02 ? T[key] : nv; }
