+  VIS[sys].led.emissive.lerp(heat ? LEDC.heat : LEDC.cool, k); VIS[sys].led.color.lerp(heat ? LEDC.heat : LEDC.cool, k);
+  VIS[sys].rvLed.emissiveIntensity = lerp(VIS[sys].rvLed.emissiveIntensity, heat ? 4 : 0, k);
+ }
+ VIS.split.louver.rotation.z = lerp(VIS.split.louver.rotation.z, heat ? .95 : .22, k);
+ VIS.mono.louver.children.forEach(v => v.rotation.z = lerp(v.rotation.z, heat ? .12 : .55, k));
+ const T = TEMPS[state.mode]; let ch = false;
+ for (const key of ['in', 'out', 'sup', 'exh']) { const nv = TD[key] + (T[key] - TD[key]) * k; if (Math.abs(nv - TD[key]) > 1e-3) ch = true; TD[key] = Math.abs(nv - T[key]) < .02 ? T[key] : nv; }
+ if (ch || !updateVisuals.init) {
+  updateVisuals.init = true;
+  $('#tIn').innerHTML = `${fmt(TD.in)}<small>°C</small>`; $('#tOut').innerHTML = `${fmt(TD.out)}<small>°C</small>`;
+  $('#tInSub').textContent = `Supply air ${fmt0(TD.sup)} °C`; $('#tOutSub').textContent = `Exhaust air ${fmt0(TD.exh)} °C`;
+ }
+}
+
+/* ===================== resize + loop ===================== */
+function resize() {
+ const w = innerWidth, h = innerHeight;
+ camera.aspect = w / h; camera.fov = w / h < 0.8 ? 44 : 32; camera.updateProjectionMatrix();
+ renderer.setPixelRatio(DPR()); renderer.setSize(w, h);
+ composer.setPixelRatio(DPR()); composer.setSize(w, h);
+ labelRenderer.setSize(w, h);
+ PU.scale.value = h * DPR() / (2 * Math.tan(camera.fov * Math.PI / 360));
+}
+addEventListener('resize', resize);
+resize();
+applySystem();
+flyTo(VIEWS.overview, 0);
+setTimeout(() => { if (!tour.on) tourStart(); }, 900);
+
+const clock = new THREE.Clock(); let simT = 0, labelTick = 0;
+renderer.setAnimationLoop(() => {
+ const dt = Math.min(clock.getDelta(), 0.05);
+ if (state.running) {
+  const sdt = dt * (reduced ? 0.4 : 1); simT += sdt; flow.step(sdt);
+  for (const f of FANS) f.o.rotation[f.ax] += f.w * sdt;
+  const cp = VIS[state.sys].comp; cp.position.y = reduced ? 0 : Math.sin(simT * 95) * .0007;
+ }
+ flow.draw(simT);
+ updateVisuals(dt, simT);
+ if (tween.active) {
+  tween.k = Math.min(1, tween.k + dt / tween.dur); const e = ease(tween.k);
+  camera.position.lerpVectors(tween.p0, tween.p1, e); controls.target.lerpVectors(tween.t0, tween.t1, e);
+  if (tween.k >= 1) tween.active = false;
+ }
+ controls.update();
+ if (tour.on && state.running) {
+  tour.t += dt; $('#tourBar').style.width = Math.min(100, tour.t / tour.dur * 100) + '%';
+  if (tour.t >= tour.dur && tour.i < STEPS[state.sys].length - 1) tourShow(tour.i + 1);
+ }
+ if ((labelTick += dt) > .25) { labelTick = 0; updateLabels(); }
+ composer.render();
+ labelRenderer.render(scene, camera);
+});
+
 </script>
