import { spawn } from 'node:child_process';
import { writeFileSync, mkdirSync } from 'node:fs';
import { resolve } from 'node:path';

const chrome = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const port = 9341, prof = resolve('.validate-profile');
mkdirSync(prof, { recursive: true });
const proc = spawn(chrome, ['--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${prof}`, '--window-size=1440,900', '--no-first-run', '--enable-unsafe-swiftshader', 'about:blank'], { stdio: 'ignore' });
const sleep = ms => new Promise(r => setTimeout(r, ms));
let list;
for (let i = 0; i < 50; i++) { try { list = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json(); if (list.find(t => t.type === 'page')) break; } catch { } await sleep(200); }
const page = list.find(t => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise(r => ws.addEventListener('open', r));
let id = 0; const pending = new Map(), errors = [];
ws.addEventListener('message', ev => {
  const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
  if (m.method === 'Runtime.exceptionThrown') errors.push('EXC ' + (m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text));
  if (m.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(m.params.type)) errors.push(m.params.type.toUpperCase() + ' ' + m.params.args.map(a => a.value ?? a.description).join(' '));
  if (m.method === 'Log.entryAdded' && m.params.entry.level === 'error') errors.push('LOG ' + m.params.entry.text + ' ' + (m.params.entry.url || ''));
});
const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async expr => (await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true })).result?.result?.value;
const shot = async f => { const r = await send('Page.captureScreenshot', { format: 'png' }); writeFileSync(f, Buffer.from(r.result.data, 'base64')); };

await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable');
const url = 'file://' + resolve('index.html');
const clicks = ['[data-sys=mono]', '[data-mode=heat]', '#btnPlay', '#btnPlay', '#btnReset', '#btnGuide', '#tourNext', '#tourNext', '#tourAct', '#tourPrev', '#btnLabels', '#btnLabels', '#btnLegend', '#btnLegend', '[data-sys=split]', '[data-mode=cool]', '#tourClose'];
async function run(label) {
  await send('Page.navigate', { url }); await sleep(7000);
  const info = await ev(`JSON.stringify({title:document.title,h1:document.querySelector('h1').textContent,boot:!!window.__acBoot,canvas:!!document.querySelector('#stage canvas'),fallback:!document.getElementById('fallback').hidden,tour:document.getElementById('tour').classList.contains('on'),labels:[...document.querySelectorAll('.lbl')].filter(e=>e.style.display!=='none').length})`);
  console.log(label, 'initial', info);
  const res = [];
  for (const s of clicks) {
    const ok = await ev(`(()=>{const b=document.querySelector('${s}'); if(!b) return 'missing'; const r=b.getBoundingClientRect(); const vis=r.width>0&&r.height>0&&getComputedStyle(b).display!=='none'; b.click(); return vis?'ok':'hidden';})()`);
    res.push(s + ':' + ok); await sleep(450);
  }
  console.log(label, 'clicks', res.join(' '));
  console.log(label, 'final', await ev(`JSON.stringify({sys:document.querySelector('#chipSys').textContent,mode:document.querySelector('#chipMode').textContent,run:document.querySelector('#chipRun').textContent,tIn:document.querySelector('#tIn').textContent,absorb:document.querySelector('#absorbAt').textContent})`));
  await sleep(1500);
  await shot(`validate-${label}.png`);
}
await run('desktop');
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 3, mobile: true });
await send('Emulation.setTouchEmulationEnabled', { enabled: true });
await run('mobile');
console.log('ERRORS', errors.length ? '\n' + errors.join('\n') : 'none');
ws.close(); proc.kill();
process.exit(0);

